package app.moire.anniversary;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.webkit.JavascriptInterface;import android.widget.RemoteViews;import org.json.*;import java.util.*;
public class MoireWidget extends AppWidgetProvider {
 static final String PREF="moire_v23";static final String CHANNEL="moire_upcoming";
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){refresh(c);}
 @Override public void onDeleted(Context c,int[] ids){refresh(c);}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(Intent.ACTION_BOOT_COMPLETED.equals(i.getAction())||Intent.ACTION_DATE_CHANGED.equals(i.getAction())||Intent.ACTION_TIMEZONE_CHANGED.equals(i.getAction()))refresh(c);}
 static JSONArray rows(JSONObject obj,String key){JSONArray a=obj.optJSONArray(key);return a==null?new JSONArray():a;}
 static String lines(JSONArray a,int max){ArrayList<JSONObject> items=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)items.add(x);}Collections.sort(items,(x,y)->Integer.compare(x.optInt("days",999999),y.optInt("days",999999)));StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(max,items.size());i++){JSONObject x=items.get(i);int d=x.optInt("days");if(i>0)b.append("\n");b.append(x.optString("name")).append("  ").append(d==0?"D-DAY":d>0?"D-"+d:"D+"+(-d));}return b.length()==0?"MOIRE에서 기념일을 선택하세요":b.toString();}
 static void refresh(Context c){try{JSONObject data=new JSONObject(c.getSharedPreferences(PREF,0).getString("data","{}"));AppWidgetManager manager=AppWidgetManager.getInstance(c);int[] ids=manager.getAppWidgetIds(new ComponentName(c,MoireWidget.class));JSONObject widgets=data.optJSONObject("widgets");for(int id:ids){JSONArray list=widgets==null?new JSONArray():rows(widgets,String.valueOf(id));RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.moire_widget);v.setTextViewText(R.id.widget_text,lines(list,5));Intent intent=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,id,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.widget_root,pi);manager.updateAppWidget(id,v);}NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"MOIRE 기념일",NotificationManager.IMPORTANCE_LOW));JSONArray list=rows(data,"notifications");if(list.length()==0){nm.cancel(2301);return;}Intent launch=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,2301,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,CHANNEL).setSmallIcon(R.mipmap.ic_launcher).setContentTitle("MOIRE · 다가오는 기념일").setContentText(lines(list,1)).setStyle(new Notification.BigTextStyle().bigText(lines(list,3))).setContentIntent(pi).setOngoing(true).setShowWhen(false).build();nm.notify(2301,n);
 }catch(Exception e){android.util.Log.e("MOIRE","Widget refresh failed",e);}}
 public static class Bridge {Context c;Bridge(Context c){this.c=c;}@JavascriptInterface public void update(String json){try{new JSONObject(json);c.getSharedPreferences(PREF,0).edit().putString("data",json).apply();new Handler(Looper.getMainLooper()).post(()->refresh(c));}catch(Exception e){android.util.Log.e("MOIRE","Invalid data",e);}}@JavascriptInterface public String getWidgetIds(){int[] ids=AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,MoireWidget.class));JSONArray array = new JSONArray();
for (int id : ids) {
    array.put(id);
}
return array.toString();;}}
}
